fits |&gt;
  filter(prior_only == 0) |&gt;
  mutate(draws = map(fit, \(f) spread_draws(f, beta))) |&gt;
  select(prior, draws) |&gt;
  unnest(draws) |&gt;
  ggplot(aes(x = beta, y = prior)) +
  stat_halfeye(fill = f2s_colors[["post"]], alpha = 0.6) +
  geom_vline(xintercept = beta_true, colour = f2s_colors[["truth"]], linewidth = 0.8) +
  labs(x = "beta", y = NULL)







图 3: 两种先验下 β 的后验分布（橙色竖线为真值 1）。宽先验下后验被拉向很大的斜率；弱信息先验下，后验集中在合理范围内。





三种结果形成鲜明对比：

glm() 的最大似然估计给出了一个荒谬的斜率，并警告“拟合概率在数值上为 0 或 1”。在准完全分离的数据上，似然会随着 \(\beta\) 增大而一直上升，最大似然估计趋向无穷。
宽先验对此几乎没有约束，后验被拉向很大的斜率，区间宽得没有实际意义。
弱信息先验把“相邻剂量之间概率不会从 0 跳到 1”这个常识写进了模型，后验落在合理范围，并覆盖了真值。

4 Stan 代码


// Chapter 6: Linear regression used to practise running and diagnosing
//
//   y_i   ~ Normal(alpha + beta * x_i, sigma)

data {
  int&lt;lower=0&gt; N;               // number of plants
  vector[N] x;                  // fertilizer dose (g), centered
  vector[N] y;                  // plant height (cm)
}

parameters {
  real alpha;                   // height at the average dose
  real beta;                    // height gain per gram of fertilizer
  real&lt;lower=0&gt; sigma;          // residual SD
}

model {
  // Priors
  target += normal_lpdf(alpha | 30, 10);
  target += normal_lpdf(beta | 0, 5);
  target += exponential_lpdf(sigma | 0.2);

  // Likelihood
  target += normal_lpdf(y | alpha + beta * x, sigma);
}

generated quantities {
  array[N] real y_rep = normal_rng(alpha + beta * x, sigma);
}

4 Stan 代码
同一个模型，三种写法。
写法一：~ 语句


model {
  mu ~ normal(150, 50);
  sigma ~ exponential(0.05);
  y ~ normal(mu, sigma);
}


写法二：target += 加 _lpdf 函数


model {
  target += normal_lpdf(mu | 150, 50);
  target += exponential_lpdf(sigma | 0.05);
  target += normal_lpdf(y | mu, sigma);
}


写法三：把正态分布的对数密度公式手工写出来


model {
  // Priors
  target += normal_lpdf(mu | 150, 50);
  target += exponential_lpdf(sigma | 0.05);

  // Likelihood, term by term
  target += -N * log(sigma)
            - 0.5 * N * log(2 * pi())
            - 0.5 * dot_self((y - mu) / sigma);
}


写法三直接来自正态分布的对数密度：
\[
\log \operatorname{Normal}(y_i \mid \mu, \sigma) = -\log\sigma - \tfrac{1}{2}\log(2\pi) - \tfrac{1}{2}\left(\frac{y_i - \mu}{\sigma}\right)^2
\]
对 \(N\) 个观测求和，就是代码中的三项。dot_self(v) 计算向量 \(v\) 各元素的平方和。
三个程序的 data 和 parameters 块完全相同，完整代码见 stan/ch04_tilde.stan、stan/ch04_target.stan 和 stan/ch04_manual.stan。

